function bilingual(raw:string):string {
 const text=raw.replace(/^(?:Error|TypeError):\s*/, '');
 if (translations[text]) return `${text} (${translations[text]})`;
 let m=text.match(/^Cannot update (.+): (\d+) sold boxes need another active stock batch, but only (\d+) boxes are available\. Add at least (\d+) boxes before trying again\.$/);
 if(m)return `${text} (${m[1]} కోసం అమ్మిన ${m[2]} బాక్సులకు మరో స్టాక్ బ్యాచ్ అవసరం. అందులో ${m[3]} బాక్సులు మాత్రమే ఉన్నాయి. మళ్లీ ప్రయత్నించే ముందు కనీసం ${m[4]} బాక్సులు జోడించండి.)`;
 m=text.match(/^Cannot update (.+): (\d+) sold boxes could not be reassigned without changing their recorded costs\.$/);
 if(m)return `${text} (${m[1]} కోసం అమ్మిన ${m[2]} బాక్సులను నమోదైన ధరలు మార్చకుండా మరో స్టాక్‌కు మార్చలేము.)`;
 m=text.match(/^(.+) removed from active lists$/);if(m)return `${text} (${m[1]} యాక్టివ్ జాబితా నుండి తొలగించబడింది)`;
 m=text.match(/^Could not export bill: (.+)$/);if(m)return `${text} (బిల్‌ను ఎగుమతి చేయలేకపోయాము: ${m[1]})`;
 if(/\([\u0c00-\u0c7f]/u.test(text))return text;
 return `${text} (సమస్య ఏర్పడింది. వివరాలను తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.)`;
}
function notify(message:string){if(message)window.alert(bilingual(message));}
function LoginGate() {
  const [signedIn, setSignedIn] = useState(!__API_BASE_URL__);
  const [password, setPassword] = useState('');
  const [error, setErrorState] = useState('');
  const [busy, setBusy] = useState(false);
  const setError=(message:string)=>{setErrorState(message);if(message)notify(message)};
  if (signedIn) return <><div style={{textAlign:'right',padding:'1rem'}}>{__API_BASE_URL__ && <button onClick={()=>{accessPassword='';setPassword('');setSignedIn(false)}}>Sign out</button>}</div><App/></>;
  return <main><section><h1>Giri Fruits</h1><h2>Sign in</h2><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');accessPassword=password;try{const r=await fetch(api+'health');if(!r.ok){accessPassword='';setError(r.status===429?'Too many attempts. Please wait 15 minutes.':'Incorrect password or service unavailable.');return;}setPassword('');setSignedIn(true)}catch{accessPassword='';setError('Cannot reach the service. Please try again.')}finally{setBusy(false)}}}><label>Password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required /></label><button disabled={busy}>{busy?'Signing in…':'Sign in'}</button>{error&&<p role="alert">{error}</p>}</form></section></main>;
}
