async function updatePaid(kind:'customer'|'dealer',id:string,amount:string){const key=`payment-${kind}-${id}`;if(!begin(key))return;try{const r=await fetch(api+(kind==='customer'?`sales/${id}/payment`:`books/dealer-bills/${id}/payment`),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({amountPaid:amount})});const v=await r.json();if(!r.ok)throw Error(v.message||'Could not update payment');setPaidDrafts(v=>{const next={...v};delete next[`${kind==='customer'?'c':'d'}-${id}`];return next;});await load();M('Amount updated');}catch(e){M(String(e));}finally{end(key)}}
function addLine(){setBillLines(v=>[...v,{productId:'',boxes:'',unitPrice:''}]);}function startEdit(b:Item){setEditingBill(b);setTab('customers');setCustomerSearch(b.customer||'');setBillDate(String(b.sale_date||'').slice(0,10)||new Date().toISOString().slice(0,10));setBillPaid(b.amount_paid||'0');setBillBalance(b.balance||'0');setPreviousOverride(null);setEditingOutstanding(false);setBillLines((b.items||[]).map(i=>({productId:String(i.product_id),boxes:String(i.quantity),unitPrice:String(i.price_per_box)})));window.scrollTo({top:0,behavior:'smooth'});}async function saveBill(e:React.FormEvent){e.preventDefault();const customer=parties.find(x=>x.role==='retailer'&&x.name===customerSearch);if(!customer){M('Select a customer from the results');return;}if(billLines.some(x=>!x.productId||!x.boxes||!x.unitPrice)){M('Choose a fruit and enter its quantity and price for every line');return;}if(!begin('customer-bill'))return;const payload={retailerId:customer.id,requestKey:editingBill?.id?`edit-${editingBill.id}-${Date.now()}`:crypto.randomUUID(),saleDate:billDate,amountPaid:billPaid,balance:billBalance,...(previousOverride===null?{}:{previousDueOverride:previousOverride}),lines:billLines.map(x=>({productId:x.productId,boxes:x.boxes,unitPrice:x.unitPrice}))};try{const r=await fetch(api+(editingBill?`sales/${editingBill.id}`:'sales'),{method:editingBill?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const v=await r.json();if(!r.ok)throw Error(v.message||'Could not save bill');setEditingBill(null);setCustomerSearch('');setBillDate(new Date().toISOString().slice(0,10));setBillPaid('0');setBillBalance('0');setPreviousOverride(null);setEditingOutstanding(false);setBillLines([{productId:'',boxes:'',unitPrice:''}]);M(editingBill?'Customer bill edited':'Customer bill added');await load();setTab('customer-bills');}catch(err){M(String(err));}finally{end('customer-bill')}}function startEditDealer(b:Item){setEditingDealerBill(b);setDealerSearch(b.dealer||'');setBillDate(String(b.bill_date||'').slice(0,10)||new Date().toISOString().slice(0,10));setBillPaid(b.amount_paid||'0');setBillBalance(b.balance||'0');setPreviousOverride(null);setEditingOutstanding(false);setBillLines((b.items||[]).map(i=>({productId:String(i.product_id),boxes:String(i.quantity),unitPrice:String(i.price_per_box),purchaseId:i.purchase_id?String(i.purchase_id):undefined})));setTab('dealers');}async function recordDealerPayment(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;try{const r=await fetch(api+'books/supplier-payments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplierId:selectedDealer,amount:new FormData(form).get('amount'),method:new FormData(form).get('method'),note:new FormData(form).get('note')})});const v=await r.json();if(!r.ok)throw Error(v.message||'Could not record payment');form.reset();M('Dealer payment recorded');await load();const detail=await fetch(api+'books/dealer-purchases/'+selectedDealer).then(x=>x.json());setDealerDetails(detail);}catch(err){M(String(err));}}
async function saveDealerBill(e:React.FormEvent){e.preventDefault();const dealer=parties.find(x=>x.role==='supplier'&&x.name===dealerSearch);if(!dealer){M('Select a dealer from the search results');return;}if(billLines.some(x=>!x.productId||!x.boxes||!x.unitPrice)){M('Choose a fruit and enter quantity and price for each line');return;}if(!begin('dealer-bill'))return;const payload={dealerId:dealer.id,billDate:billDate,amountPaid:billPaid,balance:billBalance,...(previousOverride===null?{}:{previousDueOverride:previousOverride}),requestKey:editingDealerBill?`dealer-edit-${editingDealerBill.id}-${Date.now()}`:crypto.randomUUID(),lines:billLines.map(x=>({productId:x.productId,boxes:x.boxes,unitPrice:x.unitPrice,...(x.purchaseId?{purchaseId:x.purchaseId}:{})}))};try{const r=await fetch(api+(editingDealerBill?`books/dealer-bills/${editingDealerBill.id}`:'books/dealer-bills'),{method:editingDealerBill?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const v=await r.json();if(!r.ok)throw Error(v.message||'Could not save dealer bill');setEditingDealerBill(null);setDealerSearch('');setSelectedDealer(dealer.id);setBillPaid('0');setBillBalance('0');setPreviousOverride(null);setEditingOutstanding(false);setBillLines([{productId:'',boxes:'',unitPrice:''}]);M('Dealer bill saved and stock updated');await load();setTab('dealer-bills');}catch(err){M(String(err));}finally{end('dealer-bill')}}
async function exportCustomerBill(b:Item,format:'pdf'|'png'){beginActivity();const host=document.createElement('div');host.style.cssText='position:fixed;left:-10000px;top:0;width:max-content;min-width:1100px;background:white';document.body.appendChild(host);const root=createRoot(host);try{flushSync(()=>root.render(<CustomerBill bill={b}/>));await document.fonts.ready;const logo=host.querySelector('img');if(logo&&!logo.complete)await new Promise<void>((resolve,reject)=>{logo.onload=()=>resolve();logo.onerror=()=>reject(new Error('Logo could not be loaded'));});const node=host.firstElementChild as HTMLElement;const data=await toPng(node,{pixelRatio:2,backgroundColor:'#ffffff'});if(format==='png'){const a=document.createElement('a');a.download=`${b.dealer?'DB':'GF'}-${b.id}.png`;a.href=data;a.click();}else{const pdf=new jsPDF({unit:'mm',format:'a4'});const img=pdf.getImageProperties(data);const width=190,height=img.height*width/img.width;const pageHeight=277;let offset=0;while(offset<height){if(offset>0)pdf.addPage();pdf.addImage(data,'PNG',10,10-offset,width,height);offset+=pageHeight;}pdf.save(`${b.dealer?'DB':'GF'}-${b.id}.pdf`);}}catch(e){M(`Could not export bill: ${String(e)}`);}finally{root.unmount();host.remove();endActivity();}}
