async function submit(e:React.FormEvent<HTMLFormElement>,path:string,prepare:(f:FormData)=>object){e.preventDefault();const form=e.currentTarget;const payload=prepare(new FormData(form)) as {name?:string;role?:string};const duplicateMessage=path==='products'?'Fruit is already added (ఈ ఫ్రూట్ ని ముందే ఆడ్ చేసారు)':payload.role==='retailer'?'Customer already added (ఈ కస్టమర్ ని ముందే ఆడ్ చేసారు)':'Dealer is already added (ఈ డీలర్ ని ముందే ఆడ్ చేసారు)';const normalize=(name:string)=>name.trim().replace(/\s+/g,' ').toLocaleLowerCase();const existing=path==='products'?products:parties.filter(p=>p.role===payload.role);if((path==='products'||path==='parties')&&payload.name&&existing.some(item=>normalize(item.name)===normalize(payload.name!))){window.alert(duplicateMessage);return;}const key=path==='products'?'add-fruit':payload.role==='retailer'?'add-customer':'add-dealer';if(!begin(key))return;try{const r=await fetch(api+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok){const message=Array.isArray(body.message)?body.message.join(', '):body.message||'Could not save';if((path==='products'||path==='parties')&&/already exists/i.test(message)){window.alert(duplicateMessage);await load();return;}throw Error(message);}form.reset();M(path==='products'?'Fruit added':path==='parties'?(payload.role==='retailer'?'Customer added':'Dealer added'):'Saved');await load();}catch(error){M(String(error));}finally{end(key)}}
